(()=>{const out={};for(const property of ['border-radius','-webkit-border-radius']){out[property]={};for(const value of ['initial','0','2px','2px 4px','1px 2px 3px','1px 2px 3px 4px','1px 2px 3px 4px 5px','10% 20%','2px / 4px','1px 2px / 3px 4px','-1px','auto']){const s=document.createElement('div').style;s.setProperty(property,value);out[property][value]={text:s.cssText,value:s.getPropertyValue(property),supported:CSS.supports(property,value),components:Array.from({length:s.length},(_,i)=>[s.item(i),s.getPropertyValue(s.item(i))])};}}const s=document.createElement('div').style;s.webkitBorderRadius='2px 4px';out.js=[s.cssText,s.webkitBorderRadius,s.borderRadius];return out})()
